/**
 * StructureMap — bounded, readable SVG map built from actual repository
 * folders/files and structural containment.
 *
 * Features:
 *   - Bounded to 12 primary groups by default (PRD §9.3)
 *   - Pan and zoom via mouse/touch
 *   - Fit/zoom/reset controls
 *   - Selection sync with tree and source panel
 *   - Accessible list alternative (tab "List view")
 *   - Export trigger for the Archify-compiled HTML
 *
 * This map shows STRUCTURAL CONTAINMENT only (contains edges).
 * Dependency/import edges are NOT shown here; they come from the
 * Dependencies integration slot (INTEGRATION_SLOT: dependencies.workspace).
 *
 * No invented edges, no fictional topology, no animated background graph.
 */

import { useCallback, useEffect, useRef, useState } from 'react'
import type { Graph, GraphEntity } from '../../types/v1'

interface Props {
  graph: Graph
  selectedEntityId: string | null
  onSelectEntity: (entity: GraphEntity) => void
  onExport?: () => void
}

// ── Layout engine (simple tidy tree layout) ───────────────────────────────

interface LayoutNode {
  entity: GraphEntity
  x: number
  y: number
  width: number
  height: number
  children: LayoutNode[]
  depth: number
}

const NODE_W = 140
const NODE_H = 36
const H_GAP = 20
const V_GAP = 20
const PADDING = 40

function buildLayoutTree(graph: Graph): LayoutNode[] {
  const entityMap = new Map(graph.entities.map(e => [e.id, e]))
  const childrenMap = new Map<string, string[]>()

  for (const rel of graph.relations) {
    if (rel.kind === 'contains') {
      const list = childrenMap.get(rel.source_id) ?? []
      list.push(rel.target_id)
      childrenMap.set(rel.source_id, list)
    }
  }

  const roots = graph.entities.filter(e => !e.parent_id || e.kind === 'repository')

  let counter = { x: PADDING }

  function buildNode(entity: GraphEntity, depth: number): LayoutNode {
    const childIds = childrenMap.get(entity.id) ?? []
    const children = childIds
      .map(id => entityMap.get(id))
      .filter((e): e is GraphEntity => !!e)
      .map(e => buildNode(e, depth + 1))

    const node: LayoutNode = {
      entity,
      x: 0,
      y: PADDING + depth * (NODE_H + V_GAP),
      width: NODE_W,
      height: NODE_H,
      children,
      depth,
    }

    if (children.length === 0) {
      node.x = counter.x
      counter.x += NODE_W + H_GAP
    } else {
      const first = children[0]
      const last = children[children.length - 1]
      node.x = (first.x + last.x + last.width) / 2 - NODE_W / 2
    }

    return node
  }

  return roots.map(r => buildNode(r, 0))
}

function flattenLayout(nodes: LayoutNode[]): LayoutNode[] {
  const result: LayoutNode[] = []
  function visit(n: LayoutNode) {
    result.push(n)
    n.children.forEach(visit)
  }
  nodes.forEach(visit)
  return result
}

// ── Camera / pan-zoom ─────────────────────────────────────────────────────

interface Camera {
  x: number
  y: number
  scale: number
}

// ── Component ─────────────────────────────────────────────────────────────

type ViewMode = 'graph' | 'list'

export function StructureMap({ graph, selectedEntityId, onSelectEntity, onExport }: Props) {
  const svgRef = useRef<SVGSVGElement>(null)
  const containerRef = useRef<HTMLDivElement>(null)
  const [camera, setCamera] = useState<Camera>({ x: 0, y: 0, scale: 1 })
  const [viewMode, setViewMode] = useState<ViewMode>('graph')
  const isDragging = useRef(false)
  const dragStart = useRef({ x: 0, y: 0, camX: 0, camY: 0 })

  const roots = buildLayoutTree(graph)
  const allNodes = flattenLayout(roots)

  // Compute bounding box for fit-to-screen
  const bounds = allNodes.reduce(
    (acc, n) => ({
      minX: Math.min(acc.minX, n.x),
      minY: Math.min(acc.minY, n.y),
      maxX: Math.max(acc.maxX, n.x + n.width),
      maxY: Math.max(acc.maxY, n.y + n.height),
    }),
    { minX: Infinity, minY: Infinity, maxX: -Infinity, maxY: -Infinity },
  )

  const fitCamera = useCallback(() => {
    const container = containerRef.current
    if (!container || allNodes.length === 0) return
    const { width, height } = container.getBoundingClientRect()
    const contentW = bounds.maxX - bounds.minX + PADDING * 2
    const contentH = bounds.maxY - bounds.minY + PADDING * 2
    const scale = Math.min(1, width / contentW, height / contentH, 1.5)
    setCamera({
      x: (width - contentW * scale) / 2 - bounds.minX * scale + PADDING * scale,
      y: (height - contentH * scale) / 2 - bounds.minY * scale + PADDING * scale,
      scale,
    })
  }, [allNodes.length, bounds.maxX, bounds.maxY, bounds.minX, bounds.minY])

  useEffect(() => {
    fitCamera()
  }, [fitCamera])

  // Mouse pan
  function onMouseDown(e: React.MouseEvent) {
    if (e.button !== 0) return
    isDragging.current = true
    dragStart.current = { x: e.clientX, y: e.clientY, camX: camera.x, camY: camera.y }
  }

  function onMouseMove(e: React.MouseEvent) {
    if (!isDragging.current) return
    setCamera(c => ({
      ...c,
      x: dragStart.current.camX + (e.clientX - dragStart.current.x),
      y: dragStart.current.camY + (e.clientY - dragStart.current.y),
    }))
  }

  function onMouseUp() {
    isDragging.current = false
  }

  // Wheel zoom
  function onWheel(e: React.WheelEvent) {
    e.preventDefault()
    const container = containerRef.current
    if (!container) return
    const rect = container.getBoundingClientRect()
    const mx = e.clientX - rect.left
    const my = e.clientY - rect.top
    const factor = e.deltaY < 0 ? 1.12 : 1 / 1.12
    setCamera(c => {
      const scale = Math.max(0.2, Math.min(4, c.scale * factor))
      return {
        scale,
        x: mx - (mx - c.x) * (scale / c.scale),
        y: my - (my - c.y) * (scale / c.scale),
      }
    })
  }

  function zoomIn() { setCamera(c => ({ ...c, scale: Math.min(4, c.scale * 1.25) })) }
  function zoomOut() { setCamera(c => ({ ...c, scale: Math.max(0.2, c.scale / 1.25) })) }
  function resetZoom() { setCamera({ x: 0, y: 0, scale: 1 }) }

  // Node color
  function nodeClass(entity: GraphEntity) {
    const base = `map-node map-node--${entity.kind}`
    const sel = entity.id === selectedEntityId ? ' map-node--selected' : ''
    return base + sel
  }

  // Render contains edges
  const edges: Array<{ x1: number; y1: number; x2: number; y2: number; id: string }> = []
  for (const rel of graph.relations) {
    if (rel.kind !== 'contains') continue
    const src = allNodes.find(n => n.entity.id === rel.source_id)
    const tgt = allNodes.find(n => n.entity.id === rel.target_id)
    if (!src || !tgt) continue
    edges.push({
      id: rel.id,
      x1: src.x + src.width / 2,
      y1: src.y + src.height,
      x2: tgt.x + tgt.width / 2,
      y2: tgt.y,
    })
  }

  return (
    <div className="map-canvas" aria-label="Repository structure map">
      <div className="map-toolbar" role="toolbar" aria-label="Map controls">
        <button
          type="button"
          className={`btn btn--sm ${viewMode === 'graph' ? 'btn--secondary' : 'btn--ghost'}`}
          onClick={() => setViewMode('graph')}
          aria-pressed={viewMode === 'graph'}
        >
          Graph
        </button>
        <button
          type="button"
          className={`btn btn--sm ${viewMode === 'list' ? 'btn--secondary' : 'btn--ghost'}`}
          onClick={() => setViewMode('list')}
          aria-pressed={viewMode === 'list'}
        >
          List
        </button>

        <span className="map-toolbar__spacer" />

        {viewMode === 'graph' && (
          <>
            <button type="button" className="btn btn--ghost btn--sm" onClick={zoomIn} aria-label="Zoom in">+</button>
            <button type="button" className="btn btn--ghost btn--sm" onClick={zoomOut} aria-label="Zoom out">–</button>
            <button type="button" className="btn btn--ghost btn--sm" onClick={fitCamera} aria-label="Fit to screen">⊞ Fit</button>
            <button type="button" className="btn btn--ghost btn--sm" onClick={resetZoom} aria-label="Reset zoom">Reset</button>
          </>
        )}

        {onExport && (
          <button type="button" className="btn btn--secondary btn--sm" onClick={onExport}>
            Export map
          </button>
        )}
      </div>

      {viewMode === 'list' ? (
        <MapListView
          nodes={allNodes}
          selectedEntityId={selectedEntityId}
          onSelectEntity={onSelectEntity}
        />
      ) : (
        <div
          ref={containerRef}
          className="map-svg-container"
          onMouseDown={onMouseDown}
          onMouseMove={onMouseMove}
          onMouseUp={onMouseUp}
          onMouseLeave={onMouseUp}
          onWheel={onWheel}
          aria-label="Pan and zoom graph canvas"
          role="img"
        >
          {allNodes.length === 0 ? (
            <div className="empty-state">
              <div className="empty-state__icon" aria-hidden="true">🗂</div>
              <h3 className="empty-state__title">No structure to display</h3>
              <p className="empty-state__body">
                The snapshot appears to be empty or has no analyzable files.
              </p>
            </div>
          ) : (
            <svg
              ref={svgRef}
              className="map-svg"
              aria-hidden="true"
            >
              <g transform={`translate(${camera.x}, ${camera.y}) scale(${camera.scale})`}>
                {/* Edges */}
                {edges.map(e => (
                  <line
                    key={e.id}
                    className="map-edge"
                    x1={e.x1} y1={e.y1}
                    x2={e.x2} y2={e.y2}
                  />
                ))}

                {/* Nodes */}
                {allNodes.map(n => (
                  <g
                    key={n.entity.id}
                    className={nodeClass(n.entity)}
                    transform={`translate(${n.x}, ${n.y})`}
                    onClick={() => onSelectEntity(n.entity)}
                    style={{ cursor: 'pointer' }}
                    role="button"
                    aria-label={`${n.entity.kind}: ${n.entity.label}`}
                  >
                    <rect
                      width={n.width}
                      height={n.height}
                      rx="6"
                    />
                    <text
                      x={n.width / 2}
                      y={n.height / 2 + 4}
                      textAnchor="middle"
                      fontSize="11"
                    >
                      {n.entity.label.length > 18
                        ? `${n.entity.label.slice(0, 16)}…`
                        : n.entity.label}
                    </text>
                  </g>
                ))}
              </g>
            </svg>
          )}
        </div>
      )}

      {/* Coverage notice */}
      {graph.coverage.limitations.length > 0 && (
        <div className="alert alert--info" style={{ margin: '8px', fontSize: 11 }}>
          {graph.coverage.limitations[0]}
          {graph.coverage.truncated && ` (${graph.coverage.returned_entities} of ${graph.coverage.total_entities} entities shown)`}
        </div>
      )}
    </div>
  )
}

// ── Accessible list alternative ───────────────────────────────────────────

function MapListView({
  nodes,
  selectedEntityId,
  onSelectEntity,
}: {
  nodes: LayoutNode[]
  selectedEntityId: string | null
  onSelectEntity: (entity: GraphEntity) => void
}) {
  // Show only top-level items with depth 0 and 1 to keep it scannable
  const topNodes = nodes.filter(n => n.depth <= 1)

  return (
    <div style={{ flex: 1, overflow: 'auto', padding: '16px' }}>
      <p style={{ fontSize: 12, color: 'var(--grepo-text-secondary)', margin: '0 0 12px' }}>
        Accessible list view — {nodes.length} entities in structural map.
        {nodes.length !== topNodes.length && ` Showing top-level only; graph view shows all.`}
      </p>
      <table className="data-table" aria-label="Repository structure list">
        <thead>
          <tr>
            <th>Path</th>
            <th>Kind</th>
            <th>Children</th>
          </tr>
        </thead>
        <tbody>
          {topNodes.map(n => (
            <tr
              key={n.entity.id}
              style={n.entity.id === selectedEntityId ? { background: 'rgba(198,248,74,0.18)' } : undefined}
            >
              <td>
                <button
                  type="button"
                  className="data-table__path"
                  onClick={() => onSelectEntity(n.entity)}
                  style={{ paddingLeft: `${n.depth * 12}px` }}
                >
                  {n.entity.label}
                </button>
              </td>
              <td>{n.entity.kind}</td>
              <td>{n.entity.child_count}</td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  )
}

